use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf}};
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-inverse-hint-alias176";
fn walk(p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,v)}else{v.push(p)}}}
fn main(){
 let p=Path::new(D).join("README.md");let mut s=fs::read_to_string(&p).unwrap();
 for n in 0..=1000{for unit in ["workers","hints","bytes","byte","files","unchanged","unit","cubic","unfiltered","prover","passes","failures","physical","logical","preflights","fixed","requests","total","fresh","workflow","samples","sample/","LOST","sourcefiles","regular","pin entries","successful","test counts","core tests","proofs","proof bindings","worker bounds","ms at","of15","KiB","MiB","PMU","cycle","on2x2","on 2x2"]{s=s.replace(&format!("{n}{unit}"),&format!("{n} {unit}"));}for prefix in ["are","remains","uses","alignment","and","contain","files:","passes","in","with","records","hardcoded","produces","masks","latency.","precedes","verification:","exports,","proofs.","ledger","Ryzen"]{s=s.replace(&format!("{prefix}{n}"),&format!("{prefix} {n}"));}}
 s=s.replace("1x2,72","1x2, 72").replace("KiBstacks","KiB stacks").replace(".15 fixed",". 15 fixed");
 for (a,b) in [("At32","At 32"),("at16","at 16"),("at32","at 32"),("for1x2","for 1x2"),("for2x2","for 2x2"),("on1x2","on 1x2"),("on2x2","on 2x2"),("of1x2","of 1x2"),("and1.12","and 1.12"),("0.33%slower","0.33% slower"),("1.12%slower","1.12% slower"),("Both32","Both 32"),("of15","of 15"),("4..12of","4..12 of"),("all204","all 204"),("All6","All 6"),("all6","all 6"),("All eight verified CPU10x","All eight verified CPU 10x"),("CPU10x target","CPU 10x target"),("96.484375%marginal","96.484375% marginal"),("1,000sample","1,000 sample"),("5%unknown","5% unknown"),("16M fixed","16M fixed"),("SDK6d83","SDK 6d83"),("source176","source 176"),("source175","source 175"),("merge54is","merge 54 is"),("161.883899ms","161.883899 ms"),("Zopro11.915591ms","Zopro 11.915591 ms"),("Aeglos7.959184ms","Aeglos 7.959184 ms"),("0.043%at","0.043% at"),("0.044%at","0.044% at"),("kind0","kind 0"),("the32-worker","the 32-worker"),("separate16-worker","separate 16-worker"),("exact128+8test","exact 128+8 test"),("sourcefiles","source files")]{s=s.replace(a,b);}
 fs::write(&p,s).unwrap();
 fs::copy("/home/ubuntu/src/zopro-perf-work/inverse-hint-alias176/format-report.rs",Path::new(D).join("artifacts/format-report.rs")).unwrap();
 let mut files=vec![];walk(Path::new(D),&mut files);files.sort();let mut sums=String::new();for f in files{if f.file_name().unwrap()=="SHA256SUMS"{continue}let h=Sha256::digest(fs::read(&f).unwrap());sums.push_str(&format!("{h:x}  {}\n",f.strip_prefix(D).unwrap().display()));}fs::write(Path::new(D).join("SHA256SUMS"),sums).unwrap();
 println!("Applied report spacing edits and refreshed checksum metadata; no measurement/test/archive rerun");
}
